</div>

<script>
  function changeQty(btn, delta) {
    const qtyDiv = btn.parentElement;
    const input = qtyDiv.querySelector('.qty-input');
    let val = parseInt(input.value) + delta;
    if (val < 1) val = 1;
    input.value = val;
  }
</script>
